import * as THREE from 'three/webgpu';
import * as tsl from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load textures via cached loaders
  const colorTexture = ctx.textureLoader.load(config.assets.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.assets.depthMapUrl);

  // Tessellated plane geometry (64x64 segments for displacement detail)
  const geometry = new THREE.PlaneGeometry(2, 1.25, 64, 64);

  // TSL nodes for displacement shader
  const uv = tsl.uv();
  const posLocal = tsl.positionLocal;
  const normalLocal = tsl.normalLocal;

  // Displacement mapping: sample depth texture and apply to vertices
  const depthSample = tsl.texture(depthTexture, uv).r;
  const displacementIntensity = tsl.uniform(0.08);
  const displacement = depthSample.mul(displacementIntensity);

  // Displace position along normal
  const displacedPosition = posLocal.add(normalLocal.mul(displacement));

  // Create material with machined-metal PBR aesthetics
  const material = new THREE.MeshStandardMaterial({
    map: colorTexture,
    metalness: 0.35,
    roughness: 0.55,
    clearcoat: 0.2,
    side: THREE.DoubleSide,
  });

  // Apply displacement node to material
  material.positionNode = displacedPosition;

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(
    config.scenePosition[0],
    config.scenePosition[1],
    config.scenePosition[2]
  );
  mesh.rotation.set(
    config.sceneRotation[0],
    config.sceneRotation[1],
    config.sceneRotation[2]
  );
  mesh.scale.set(
    config.sceneScale[0],
    config.sceneScale[1],
    config.sceneScale[2]
  );

  group.add(mesh);

  // Store original position for hover animation
  const originalY = mesh.position.y;
  let hoverTween = null;

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](mesh, primitive.params || {});
      }
    });
  }

  // Attach event handlers
  group.userData.handlers = {
    pointerenter: () => {
      if (hoverTween) hoverTween.kill();
      // Rise-in hover effect: 0.15 scene units upward
      hoverTween = gsap.to(mesh.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    pointerleave: () => {
      if (hoverTween) hoverTween.kill();
      // Return to original position
      hoverTween = gsap.to(mesh.position, {
        y: originalY,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    click: () => {
      // Emit pricing selection event
      if (typeof config.onEvent === 'function') {
        config.onEvent('hub-pricing.select');
      }
    }
  };

  // Cleanup resources
  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
  };

  return group;
}
